  ArrowLeft, CheckCircle2, Loader2, Mail, Link as LinkIcon, 
  Fingerprint, building2
} from 'lucide-react';

const Register = () => {
  const [showModal, setShowModal] = useState(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [verifyingStep, setVerifyingStep] = useState(''); 
  const [isSuccess, setIsSuccess] = useState(false);
  const [error, setError] = useState('');
  
  const navigate = useNavigate();
  const bgImage = "https://i.pinimg.com/1200x/3d/da/0d/3dda0d2769ba87e3b59597ba56f6548e.jpg";

  // Detailed Form State
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    college: '',
    skills: '',
    companyName: '',
    website: '',
    regId: ''
  });

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    if (error) setError('');
  };

  const startVerification = (e) => {
    e.preventDefault();
    setIsVerifying(true);
    setError('');

    // High-End Security Simulation Steps
    const steps = [
      "Initializing Secure Connection...",
      "Scanning Uploaded Documents...",
      "Matching Identity with Database...",
      "Validating Professional Credentials...",
      "Finalizing Security Clearance..."
    ];

    let stepIdx = 0;
    const interval = setInterval(() => {
      setVerifyingStep(steps[stepIdx]);
      stepIdx++;

      if (stepIdx >= steps.length) {
        clearInterval(interval);
        finalizeCheck();
      }
    }, 700);
  };

  const finalizeCheck = () => {
    // Professional Validation Logic
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const isEmailValid = emailPattern.test(formData.email);
    const hasRequiredInfo = showModal === 'studet' 
      ? (formData.fullName.length > 3 && formData.skills.length > 2)
      : (formData.companyName.length > 2 && formData.regId.length > 3);

    if (isEmailValid && hasRequiredInfo) {
      setIsVerifying(false);
      setIsSuccess(true);
      // Final Redirect to Dashboard
      setTimeout(() => navigate('/admin'), 2200);
    } else {
      setIsVerifying(false);
      setError("Verification Terminated: Data integrity check failed. Please ensure all official fields are accurate.");
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 font-sans bg-cover bg-center relative overflow-hidden"
      style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.85), rgba(88, 28, 135, 0.75)), url(${bgImage})` }}>
      
      {/* Back Navigation */}
      <button 
        onClick={() => navigate('/home')} 
        className="absolute top-8 left-8 z-20 flex items-center gap-2 text-white/50 hover:text-white transition-all font-black text-xs tracking-widest uppercase"
      >
        <ArrowLeft size={16} /> Exit to Login
      </button>

      {/* Main Selection Area */}
      {!showModal && (
        <div className="z-10 text-center animate-in fade-in slide-in-from-bottom-10 duration-1000">
           <div className="inline-flex items-center gap-2 bg-white/10 backdrop-blur-md px-4 py-2 rounded-full border border-white/20 mb-6">
              <Fingerprint size={16} className="text-purple-400" />
              <span className="text-[10px] font-black text-white uppercase tracking-[0.3em]">Identity Authentication Required</span>
           </div>
           <h1 className="text-6xl font-black text-white mb-10 tracking-tighter">Choose Your <span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-blue-400">Portal</span></h1>
           
           <div className="bg-white/5 backdrop-blur-3xl p-4 rounded-[3.5rem] flex border border-white/10 w-full max-w-2xl shadow-2xl">
              <button 
                onClick={() => setShowModal('student')} 
                className="flex-1 py-16 rounded-[3rem] hover:bg-purple-600/40 transition-all group flex flex-col items-center border border-transparent hover:border-purple-500/50"
              >
                <div className="bg-purple-500/20 p-6 rounded-3xl mb-4 group-hover:scale-110 transition-transform">
                  <User size={48} className="text-purple-400 group-hover:text-white" />
                </div>
                <span className="text-white font-black text-xl tracking-tight">STUDENT</span>
                <p className="text-purple-300/40 text-[10px] font-bold mt-2 uppercase">Verified Profiles</p>
              </button>

              <div className="w-[1px] bg-white/10 my-10"></div>

              <button 
                onClick={() => setShowModal('hr')} 
                className="flex-1 py-16 rounded-[3rem] hover:bg-blue-600/40 transition-all group flex flex-col items-center border border-transparent hover:border-blue-500/50"
              >
                <div className="bg-blue-500/20 p-6 rounded-3xl mb-4 group-hover:scale-110 transition-transform">
                  <Briefcase size={48} className="text-blue-400 group-hover:text-white" />
                </div>
                <span className="text-white font-black text-xl tracking-tight">RECRUITER</span>
                <p className="text-blue-300/40 text-[10px] font-bold mt-2 uppercase">Corporate Access</p>
              </button>
           </div>
        </div>
      )}

      {/* Identity Check Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-2xl flex items-center justify-center z-50 p-4">
          {!isSuccess ? (
            <div className="bg-white w-full max-w-3xl rounded-[3.5rem] shadow-2xl overflow-hidden animate-in zoom-in duration-500">
              
              {/* Modal Header */}
              <div className={`p-10 text-white flex justify-between items-center ${showModal === 'student' ? 'bg-gradient-to-r from-indigo-600 to-purple-600' : 'bg-gradient-to-r from-blue-600 to-cyan-600'}`}>
                <div className="flex items-center gap-5">
                  <div className="bg-white/20 p-4 rounded-2xl backdrop-blur-md shadow-inner">
                    <ShieldCheck size={36} />
                  </div>
                  <div>
                    <h2 className="text-3xl font-black uppercase tracking-tighter">Security Protocol</h2>
                    <p className="text-xs font-bold opacity-70 tracking-[0.2em] uppercase">Professional Tier Verification</p>
                  </div>
                </div>
                <button onClick={() => setShowModal(null)} className="hover:bg-black/20 p-3 rounded-full transition-colors"><X size={28} /></button>
              </div>

              {/* Form Content */}
              <form onSubmit={startVerification} className="p-12 grid grid-cols-1 md:grid-cols-2 gap-6 max-h-[70vh] overflow-y-auto custom-scrollbar bg-gray-50/30">
                
                {error && (
                  <div className="col-span-2 bg-red-50 text-red-600 p-5 rounded-2xl text-[10px] font-black uppercase border border-red-100 flex items-center gap-3 animate-pulse">
                    <X className="bg-red-600 text-white rounded-full p-1" size={20} />
                    {error}
                  </div>
                )}

                {showModal === 'student' ? (
                  <>
                    <div className="col-span-2 text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-[-10px]">Academic Details</div>
                    <input type="text" name="fullName" placeholder="Full Legal Name" className="input-style" onChange={handleInputChange} required />
                    <input type="text" name="college" placeholder="University Name" className="input-style" onChange={handleInputChange} required />
                    <input type="email" name="email" placeholder="Student Email (@edu)" className="input-style" onChange={handleInputChange} required />
                    <input type="text" name="skills" placeholder="Core Expertise (React, Python...)" className="input-style" onChange={handleInputChange} required />
                    
                    <div className="col-span-2 mt-4 p-10 border-2 border-dashed border-indigo-100 rounded-[2.5rem] bg-white text-center hover:border-indigo-400 transition-colors group cursor-pointer">
                       <FileText className="mx-auto text-indigo-300 mb-3 group-hover:scale-110 transition-transform" size={40} />
                       <h3 className="text-sm font-black text-gray-800 uppercase tracking-tight">Professional Resume</h3>
                       <p className="text-[10px] text-gray-400 mt-1 uppercase font-bold">PDF / DOCX format only</p>
                       <input type="file" className="hidden" id="resume" required />
                       <label htmlFor="resume" className="mt-5 inline-block bg-indigo-600 text-white px-8 py-2.5 rounded-full text-[10px] font-black tracking-widest cursor-pointer hover:bg-indigo-700">UPLOAD FILE</label>
                    </div>
                  </>
                ) : (
                  <>
                    <div className="col-span-2 text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] mb-[-10px]">Corporate Credentials</div>
                    <input type="text" name="companyName" placeholder="Full Registered Entity Name" className="input-style" onChange={handleInputChange} required />
                    <input type="text" name="website" placeholder="Corporate Website URL" className="input-style" onChange={handleInputChange} required />
                    <input type="email" name="email" placeholder="Official HR Mail (@company)" className="input-style" onChange={handleInputChange} required />
                    <input type="text" name="regId" placeholder="Tax Registration / License ID" className="input-style" onChange={handleInputChange} required />
                    
                    <div className="col-span-2 mt-4 p-10 border-2 border-dashed border-blue-100 rounded-[2.5rem] bg-white text-center hover:border-blue-400 transition-colors group cursor-pointer">
                       <Award className="mx-auto text-blue-300 mb-3 group-hover:scale-110 transition-transform" size={40} />
                       <h3 className="text-sm font-black text-gray-800 uppercase tracking-tight">Business Verification Docs</h3>
                       <p className="text-[10px] text-gray-400 mt-1 uppercase font-bold">Proof of incorporation</p>
                       <input type="file" className="hidden" id="bizDoc" required />
                       <label htmlFor="bizDoc" className="mt-5 inline-block bg-blue-600 text-white px-8 py-2.5 rounded-full text-[10px] font-black tracking-widest cursor-pointer hover:bg-blue-700">SELECT DOCUMENTS</label>
                    </div>
                  </>
                )}

                <button 
                  type="submit" 
                  disabled={isVerifying} 
                  className={`col-span-2 py-7 rounded-[2rem] font-black text-white shadow-2xl flex items-center justify-center gap-4 mt-6 transition-all transform active:scale-[0.98] ${
                    isVerifying ? 'bg-amber-500' : (showModal === 'student' ? 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-200')
                  }`}
                >
                  {isVerifying ? (
                    <>
                      <Loader2 className="animate-spin" size={24} />
                      <span className="uppercase tracking-[0.2em] text-xs font-black">{verifyingStep}</span>
                    </>
                  ) : (
                    <span className="tracking-[0.3em] text-sm">INITIATE CLEARANCE</span>
                  )}
                </button>
              </form>
            </div>
          ) : (
            /* SUCCESS FEEDBACK */
            <div className="text-center animate-in zoom-in duration-700">
              <div className="w-32 h-32 bg-green-500 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-[0_20px_60px_rgba(34,197,94,0.4)] rotate-12">
                <CheckCircle2 size={64} className="text-white animate-pulse" />
              </div>
              <h2 className="text-6xl font-black text-white uppercase tracking-tighter">Verified</h2>
              <p className="text-green-300 font-bold uppercase tracking-[0.4em] text-xs mt-4">Security Access Granted • Admin Redirect</p>
            </div>
          )}
        </div>
      )}

      {/* Styles for the inputs and custom scrollbar */}
      <style>{`
        .input-style {
          width: 100%;
          padding: 1.25rem 1.75rem;
          background-color: white;
          border: 2px solid #f1f5f9;
          border-radius: 1.5rem;
          outline: none;
          transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
          font-weight: 700;
          font-size: 0.95rem;
          color: #1e293b;
        }
        .input-style:focus {
          border-color: #6366f1;
          background-color: white;
          box-shadow: 0 15px 30px -10px rgba(99, 102, 241, 0.2);
          transform: translateY(-3px);
        }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default Register;
